class Solution {
public:
    bool isSealed(string& s) {
        string t = s;
        bool changed = true;
        while (changed) {
            changed = false;
            for (const char* p : {"()", "[]", "{}"}) {
                size_t i;
                while ((i = t.find(p)) != string::npos) { t.erase(i, 2); changed = true; }
            }
        }
        return t.empty();
    }
};

