bool isSealed(char* s) {
    int n = strlen(s);
    char* t = malloc(n + 1);
    memcpy(t, s, n + 1);
    bool changed = true;
    while (changed) {
        changed = false;
        int w = 0;
        for (int i = 0; t[i]; i++) {
            char c = t[i], d = t[i + 1];
            if ((c == '(' && d == ')') || (c == '[' && d == ']') || (c == '{' && d == '}')) { i++; changed = true; continue; }
            t[w++] = c;
        }
        t[w] = '\0';
    }
    bool sealed = t[0] == '\0';
    free(t);
    return sealed;
}

