    bool isSealed(string& s) {
        vector<char> stack;
        for (char c : s) {
            if (c == '(' || c == '[' || c == '{') stack.push_back(c);
            else {
                char want = c == ')' ? '(' : c == ']' ? '[' : '{';
                if (stack.empty() || stack.back() != want) return false;
                stack.pop_back();
            }
        }
        return stack.empty();
    }
};

