bool isSealed(char* s) {
    int n = strlen(s), top = 0;
    char* stack = malloc(n + 1);
    bool ok = true;
    for (int i = 0; i < n && ok; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') stack[top++] = c;
        else {
            char want = c == ')' ? '(' : c == ']' ? '[' : '{';
            if (top == 0 || stack[top - 1] != want) ok = false;
            else top--;
        }
    }
    ok = ok && top == 0;
    free(stack);
    return ok;
}
